function purchaseTowerSkin(raw,id,now=null,expectedHour=null){const p=C.normalizeProfile(raw),s=towerSkins.find(s=>s.id===id);if(!s||s.free)return{ok:false,profile:p,reason:'Unknown tower skin'};if(now!==null&&(hourlyKey(now)!==expectedHour||!rotatingTowerSkins(now).some(s=>s.id===id)))return{ok:false,profile:p,reason:'This offer expired. Refresh the shop.'};if(p.ownedTowerSkins.includes(id))return{ok:false,profile:p,reason:'Tower skin already owned'};if(p.gems<s.cost)return{ok:false,profile:p,reason:'Not enough gems'};p.gems-=s.cost;p.ownedTowerSkins.push(id);return{ok:true,profile:p};}
function selectTowerSkin(raw,id){const p=C.normalizeProfile(raw);if(!Cos.validSkin(id)||!p.ownedTowerSkins.includes(id))return{ok:false,profile:p,reason:'Unlock this tower skin first'};p.selectedTowerSkin=id;return{ok:true,profile:p};}
function equipEmote(raw,id){const p=C.normalizeProfile(raw);if(!p.ownedEmotes.includes(id))return{ok:false,profile:p,reason:'Unlock this emote first'};if(p.equippedEmotes.includes(id))p.equippedEmotes=p.equippedEmotes.filter(e=>e!==id);else {if(p.equippedEmotes.length>=8)p.equippedEmotes.pop();p.equippedEmotes.push(id);}return{ok:true,profile:p};}
function age(when,now=Date.now()){if(!Number.isFinite(Number(when))||!Number.isFinite(now))return 'Earlier';const min=Math.max(0,Math.floor((now-Number(when))/60000));if(min===0)return 'Just now';if(min<60)return min+'min ago';const h=Math.floor(min/60);return h<24?h+'h '+min%60+'min ago':Math.floor(h/24)+'d '+h%24+'h ago';}
function purchaseEmote(raw,id,now=null,expectedHour=null){const p=C.normalizeProfile(raw),e=emotes.find(e=>e.id===id);if(!e||e.free||e.roadOnly)return {ok:false,profile:p,reason:'Unknown shop emote'};if(now!==null&&(hourlyKey(now)!==expectedHour||!rotatingEmotes(now).some(e=>e.id===id)))return {ok:false,profile:p,reason:'This offer expired. Refresh the shop.'};if(p.ownedEmotes.includes(id))return {ok:false,profile:p,reason:'Emote already owned'};if(p.gems<e.cost)return {ok:false,profile:p,reason:'Not enough gems'};p.gems-=e.cost;p.ownedEmotes.push(id);return {ok:true,profile:p};}
