function swipeDirection(dx,dy,scale,elapsed){return [dx,dy,scale,elapsed].every(Number.isFinite)&&scale>0&&elapsed>=0&&elapsed<3500&&Math.abs(dx)>90*scale&&Math.abs(dx)>Math.abs(dy)*2?(dx<0?1:-1):0;}
